{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Invest — {{BUSINESS_NAME}} Pricing</title>
  <meta name="description" content="Flexible supports & modular care options — choose a path that fits real life.">
  <style>
    :root{--bg:#fbfbf9;--muted:#6b6b6b;--accent:#2e6b5a;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;font-weight:400;color:#1b1b1b;background:var(--bg)}
    a{text-decoration:none;color:inherit}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:10}
    nav{display:flex;gap:18px;align-items:center;font-size:14px}
    .brand{font-weight:700;color:var(--accent)}
    .hero{padding:48px 28px 36px;display:grid;grid-template-columns:1fr;gap:20px;align-items:center;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 240 240"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="%232e6b5a" stop-opacity="0.06"/><stop offset="1" stop-color="%231b1b1b" stop-opacity="0.02"/></linearGradient></defs><rect width="240" height="240" fill="%23fbfbf9"/><g fill="none" stroke="%232e6b5a" stroke-opacity="0.08" stroke-width="1"><path d="M0 20h240M0 60h240M0 100h240M0 140h240M0 180h240M0 220h240"/></g><g fill="%232e6b5a" fill-opacity="0.06"><circle cx="40" cy="40" r="4"/><circle cx="200" cy="60" r="5"/><circle cx="80" cy="160" r="6"/><circle cx="160" cy="200" r="3"/></g><g fill="url(%23g)" opacity="0.9"><rect x="0" y="0" width="240" height="12"/></g></svg>');background-repeat:repeat;padding-bottom:60px}
    .hero .lead{max-width:62ch}
    h1{margin:0;font-size:28px;letter-spacing:-0.02em}
    p.lede{margin:8px 0 0;color:var(--muted);line-height:1.5}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:20px 0}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(17,17,17,0.04);border:1px solid rgba(17,17,17,0.03)}
    .price{font-weight:700;font-size:20px;color:var(--accent)}
    .muted{color:var(--muted);font-size:14px}

    .planner .panel{display:grid;gap:10px}
    label{font-size:13px;color:#222}
    input[type="text"],textarea,select{width:100%;padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.08);background:transparent}
    .checks{display:flex;flex-wrap:wrap;gap:8px}
    .chip{padding:8px 10px;border-radius:999px;background:var(--glass);border:1px solid rgba(0,0,0,0.04);font-size:13px}
    .actions{display:flex;gap:10px;align-items:center}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .btn.secondary{background:transparent;border:1px solid rgba(0,0,0,0.08);color:inherit}
    pre.summary{white-space:pre-wrap;background:#f7f7f6;padding:12px;border-radius:8px;border:1px dashed rgba(0,0,0,0.04);font-family:inherit}
    .faq p{margin:8px 0;color:var(--muted)}
    footer{padding:28px;border-top:1px solid rgba(0,0,0,0.03);display:flex;justify-content:space-between;align-items:center;font-size:14px}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 420ms ease,transform 420ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="lead">
        <h1>Care you can schedule into your life — paced and practical</h1>
        <p class="lede">Choose a modular path: short, focused moments of support that compound into steadier days. Pricing is framed as access levels rather than promises; we build options to meet how you live.</p>
      </div>
      <div class="muted">Questions? Call us: <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </section>

    <section class="packages reveal" aria-labelledby="packages-title">
      <h2 id="packages-title">Access tiers & pathways</h2>
      <div class="grid">
        <div class="card">
          <div class="muted">Entry — Single Sessions</div>
          <div class="price">$95 — $130</div>
          <p class="muted">One-off visits for focused concerns: testing, an acute review, or a reset. Educational and practical.</p>
        </div>
        <div class="card">
          <div class="muted">Rooting Package</div>
          <div class="price">3 sessions / $270</div>
          <p class="muted">Short course to clarify priorities and immediate supports.</p>
        </div>
        <div class="card">
          <div class="muted">Compass Program</div>
          <div class="price">6 sessions / $510</div>
          <p class="muted">A steady check-in rhythm to start building habits and tracking progress.</p>
        </div>
        <div class="card">
          <div class="muted">Renewal Plan</div>
          <div class="price">12 sessions / $960</div>
          <p class="muted">Structured continuity for people ready to layer supports and see measurable change.</p>
        </div>
      </div>
      <p class="muted">All programs are adaptable. Add-on learning modules, guided practices, and resource bundles available. Insurance eligibility varies; we provide receipts and necessary documentation where appropriate.</p>
    </section>

    <section class="planner card reveal" aria-labelledby="planner-title">
      <h2 id="planner-title">Session Planner</h2>
      <div class="panel">
        <label for="p-name">Your name</label>
        <input id="p-name" type="text" placeholder="First and last">

        <label for="p-goal">Primary goal or concern</label>
        <textarea id="p-goal" rows="3" placeholder="Sleep, energy, digestion, stress, etc."></textarea>

        <label>Focus areas</label>
        <div class="checks" id="p-focus">
          <button type="button" class="chip" data-value="Sleep">Sleep</button>
          <button type="button" class="chip" data-value="Energy">Energy</button>
          <button type="button" class="chip" data-value="Mood">Mood</button>
          <button type="button" class="chip" data-value="Digestion">Digestion</button>
          <button type="button" class="chip" data-value="Stress">Stress</button>
        </div>

        <label for="p-sessions">Preferred cadence</label>
        <select id="p-sessions">
          <option value="1">1 session / month</option>
          <option value="2">2 sessions / month</option>
          <option value="4">Weekly sessions</option>
        </select>

        <label>Modalities you prefer</label>
        <div class="checks" id="p-modal">
          <button type="button" class="chip" data-value="Nutrition">Nutrition</button>
          <button type="button" class="chip" data-value="Movement">Movement</button>
          <button type="button" class="chip" data-value="Breathwork">Breathwork</button>
          <button type="button" class="chip" data-value="Herbal Support">Herbal Support</button>
          <button type="button" class="chip" data-value="Counseling">Counseling</button>
        </div>

        <div class="actions">
          <button class="btn" id="build-plan">Build plan</button>
          <button class="btn secondary" id="clear-plan">Reset</button>
        </div>

        <label for="summary">Plan summary (plain text)</label>
        <pre id="summary" class="summary" aria-live="polite">Your personalized plan will appear here after you click "Build plan".</pre>
        <div class="actions">
          <button class="btn" id="copy-plan">Copy summary</button>
          <button class="btn secondary" id="download-plan">Download .txt</button>
          <div id="copy-note" class="muted" style="padding-left:8px"></div>
        </div>
      </div>
    </section>

    <section class="faq reveal">
      <h3>Notes</h3>
      <p class="muted">Services are educational and supportive. We do not promise cures. Your clinician will suggest a practical plan; outcomes vary by person and engagement.</p>
    </section>

    <section class="card reveal" style="margin:20px 0">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
        <div>
          <strong>Ready to begin?</strong>
          <div class="muted">Book a discovery session to review options and fit.</div>
        </div>
        <div>
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="muted">{{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div class="muted">Call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // Scroll reveal (respects prefers-reduced-motion)
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced){els.forEach(e=>e.classList.add('visible'));return}
      if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries)=>{
          entries.forEach(ent=>{ if(ent.isIntersecting){ ent.target.classList.add('visible'); io.unobserve(ent.target); } });
        },{threshold:0.12});
        els.forEach(e=>io.observe(e));
      } else {
        const onScroll = ()=>{
          els.forEach(e=>{
            const r = e.getBoundingClientRect();
            if(r.top < window.innerHeight - 60) e.classList.add('visible');
          });
        };
        onScroll();window.addEventListener('scroll',onScroll);
      }
    })();

    // Planner widget
    (function(){
      const toggleChip = (btn)=>btn.classList.toggle('active');
      document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{b.classList.toggle('active')}));

      const getActive = (container)=>Array.from(container.querySelectorAll('.chip.active')).map(n=>n.dataset.value);

      const buildBtn = document.getElementById('build-plan');
      const copyBtn = document.getElementById('copy-plan');
      const downloadBtn = document.getElementById('download-plan');
      const clearBtn = document.getElementById('clear-plan');
      const summaryEl = document.getElementById('summary');
      const noteEl = document.getElementById('copy-note');

      const buildText = ()=>{
        const name = document.getElementById('p-name').value.trim() || 'Client';
        const goal = document.getElementById('p-goal').value.trim() || 'General wellness';
        const cadence = document.getElementById('p-sessions').value;
        const focus = getActive(document.getElementById('p-focus'));
        const modal = getActive(document.getElementById('p-modal'));
        const lines = [];
        lines.push(`${name} — session plan`);
        lines.push('Primary focus: ' + goal);
        if(focus.length) lines.push('Focus areas: ' + focus.join(', '));
        if(modal.length) lines.push('Preferred approaches: ' + modal.join(', '));
        lines.push('Suggested cadence: ' + cadence + ' session(s) per month');

        // A minimal, educational suggestion tier
        let suggestion = '';
        if(cadence === '1') suggestion = 'Short-term check-ins to establish quick changes; pair with at-home practices.';
        else if(cadence === '2') suggestion = 'Regular touchpoints to adjust supports and measure progress.';
        else suggestion = 'Weekly rhythm for deeper habit work and iterative adjustments.';
        lines.push('Suggested support style: ' + suggestion);

        lines.push('Notes: This is a draft plan to discuss with a clinician. Not a medical guarantee.');
        return lines.join('\n');
      };

      buildBtn.addEventListener('click',()=>{
        const text = buildText();
        summaryEl.textContent = text;
        noteEl.textContent = 'Plan ready — copy or download.';
      });

      copyBtn.addEventListener('click',async()=>{
        try{
          await navigator.clipboard.writeText(summaryEl.textContent);
          noteEl.textContent = 'Copied to clipboard.';
          setTimeout(()=>noteEl.textContent = '',1800);
        }catch(e){
          noteEl.textContent = 'Copy failed — select and copy manually.';
        }
      });

      downloadBtn.addEventListener('click',()=>{
        const blob = new Blob([summaryEl.textContent || buildText()],{type:'text/plain;charset=utf-8'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;a.download = 'session-plan.txt';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
      });

      clearBtn.addEventListener('click',()=>{
        document.getElementById('p-name').value='';
        document.getElementById('p-goal').value='';
        document.getElementById('p-sessions').value='1';
        document.querySelectorAll('.chip.active').forEach(c=>c.classList.remove('active'));
        summaryEl.textContent='Your personalized plan will appear here after you click "Build plan".';
        noteEl.textContent='';
      });
    })();
  </script>
</body>
</html>"} 
