<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Studio — About {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--ink:#111;--calm:#2e6b5a;--muted:#6f6f6f}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:var(--ink);background:linear-gradient(180deg,#ffffff 0%,#fbfbfb 100%)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;position:sticky;top:0;background:rgba(255,255,255,0.85);backdrop-filter:blur(4px)}
    nav{display:flex;gap:16px;font-size:14px}
    main{max-width:980px;margin:28px auto;padding:0 18px}

    .hero{display:flex;gap:20px;align-items:center}
    .badge{padding:8px 12px;border-radius:999px;background:var(--calm);color:#fff;font-weight:600}
    h1{margin:6px 0 0;font-size:28px}
    .intro{color:var(--muted);max-width:64ch}

    .story, .values, .team{margin-top:20px}
    .card{background:#fff;border-radius:12px;padding:16px;border:1px solid rgba(0,0,0,0.04);box-shadow:0 6px 18px rgba(14,14,14,0.03)}

    .reveal{opacity:0;transform:translateY(14px);transition:opacity 360ms ease,transform 360ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" aria-labelledby="about-title">
      <div>
        <div class="badge">Small studio</div>
        <h1 id="about-title">A quietly rigorous practice</h1>
        <p class="intro">We combine practical testing, movement, nourishment, and listening to create plans that fit the messy rhythms of real life. The goal is steady improvement, not perfection.</p>
      </div>
      <div class="muted" style="color:var(--muted)">Serving {{CITY}}, {{STATE}} — contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </section>

    <section class="story reveal card" aria-labelledby="story-title">
      <h2 id="story-title">How this grew</h2>
      <p class="muted">Started from a hopeful curiosity: what if health care were designed around habits, not crises? We built a small practice that prioritizes actionable insights and teaches skills clients can use between visits. Our clinicians blend evidence, experience, and a human rhythm.</p>
    </section>

    <section class="values reveal">
      <div class="card">
        <h3>Core approach</h3>
        <ul>
          <li>Listen first — understand life context before recommending next steps.</li>
          <li>Offer modular supports — short, layered steps you can try between visits.</li>
          <li>Measure simply — simple markers, clear adjustments.</li>
        </ul>
      </div>
    </section>

    <section class="team reveal">
      <div class="card">
        <h3>People & roles</h3>
        <p class="muted">Our team blends nutrition, movement coaching, and mind-body counseling. Each clinician holds licenses and continuing education in integrative modalities. If you have specific needs we match you to the clinician best-suited for that work.</p>
      </div>
    </section>

    <section class="card reveal" style="margin-top:18px">
      <h3>Practical invitation</h3>
      <p class="muted">If you'd like, book a short discovery visit. We'll clarify priorities and outline a modest number of first steps. No hard sales — just options, with transparent pricing.</p>
      <div style="margin-top:12px"><a class="btn" href="{{PRIMARY_CTA_URL}}" style="background:var(--calm);color:#fff;padding:10px 14px;border-radius:8px;display:inline-block">Reserve a short visit</a></div>
    </section>
  </main>

  <footer style="padding:18px;text-align:center;color:var(--muted)">© <span id="yr"></span> {{BUSINESS_NAME}} — <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{CITY}}, {{STATE}}</footer>

  <script>
    // reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced){els.forEach(e=>e.classList.add('visible'));return}
      const io = ('IntersectionObserver' in window) && new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');io.unobserve(en.target)}}),{threshold:0.1});
      if(io){els.forEach(e=>io.observe(e));} else {els.forEach(e=>e.classList.add('visible'))}
    })();
    document.getElementById('yr').textContent = new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Visit — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfcfb;--accent:#2e6b5a;--muted:#666}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#111}
    header{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;position:sticky;top:0;background:rgba(255,255,255,0.85);backdrop-filter:blur(3px)}
    nav{display:flex;gap:14px}
    main{max-width:840px;margin:28px auto;padding:0 18px}

    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:#fff;padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    label{display:block;margin:10px 0 6px;font-size:13px;color:var(--muted)}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    .muted{color:var(--muted)}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 360ms ease,transform 360ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <h1 class="reveal">Reserve time with a clinician</h1>
    <p class="muted reveal">Book a discovery or a standard visit. If you're unsure, start with a short discovery so we can recommend a tailored plan.</p>

    <div class="grid">
      <section class="panel reveal">
        <h2>Request form</h2>
        <form id="booking-form">
          <label for="name">Name</label>
          <input id="name" type="text" required>

          <label for="email">Email</label>
          <input id="email" type="email" required>

          <label for="phone">Phone</label>
          <input id="phone" type="tel">

          <label for="type">Visit type</label>
          <select id="type">
            <option>Discovery (20–30 min)</option>
            <option>Standard consult (50 min)</option>
            <option>Follow-up (25 min)</option>
          </select>

          <label for="notes">Brief notes for clinician</label>
          <textarea id="notes" rows="3"></textarea>

          <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
            <button class="btn" type="submit">Request time</button>
            <div class="muted">We will reach out to confirm availability.</div>
          </div>
        </form>
      </section>

      <aside class="panel reveal" aria-labelledby="planner-title">
        <h3 id="planner-title">Session Planner (quick)</h3>
        <p class="muted">Draft a short plan to bring to your visit — copy it to your clipboard or download a text file to attach to your message.</p>
        <label for="s-name">Your name</label>
        <input id="s-name" type="text" placeholder="Name">
        <label for="s-goal">One-line goal</label>
        <input id="s-goal" type="text" placeholder="Sleep / Digestion / Energy">
        <label>Modalities</label>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button class="chip" data-val="Nutrition" type="button">Nutrition</button>
          <button class="chip" data-val="Movement" type="button">Movement</button>
          <button class="chip" data-val="Mindfulness" type="button">Mindfulness</button>
        </div>

        <label for="s-cadence">Cadence</label>
        <select id="s-cadence">
          <option value="1">1 / month</option>
          <option value="2">2 / month</option>
          <option value="4">Weekly</option>
        </select>

        <div style="margin-top:12px;display:flex;gap:8px">
          <button class="btn" id="s-build">Create</button>
          <button class="btn" id="s-copy" type="button">Copy</button>
        </div>
        <pre id="s-out" style="margin-top:10px;background:#f7f7f6;padding:10px;border-radius:8px;white-space:pre-wrap">No plan yet.</pre>
      </aside>
    </div>

    <section class="panel reveal" style="margin-top:18px">
      <h3>Booking notes</h3>
      <p class="muted">Appointments are educational and supportive. We provide receipts; check with your insurer about coverage. If you have an urgent medical concern, please use emergency services or contact your primary care provider.</p>
    </section>
  </main>

  <footer style="padding:18px;text-align:center;color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></footer>

  <script>
    // reveal logic
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced){els.forEach(e=>e.classList.add('visible'));return}
      if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');io.unobserve(en.target)}});},{threshold:0.12});
        els.forEach(e=>io.observe(e));
      } else {els.forEach(e=>e.classList.add('visible'))}
    })();

    // Booking form (local, no backend): gather and prepare an email-link
    document.getElementById('booking-form').addEventListener('submit',function(e){
      e.preventDefault();
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      const phone = document.getElementById('phone').value.trim();
      const type = document.getElementById('type').value;
      const notes = document.getElementById('notes').value.trim();
      const subject = encodeURIComponent('Booking request: ' + (name || 'Client'));
      const body = encodeURIComponent('Name: ' + name + '\nEmail: ' + email + '\nPhone: ' + phone + '\nRequested: ' + type + '\nNotes:\n' + notes);
      // open user's mail client with draft
      window.location.href = 'mailto:{{EMAIL}}?subject=' + subject + '&body=' + body;
    });

    // Small planner for booking page
    (function(){
      const chips = document.querySelectorAll('button.chip');
      chips.forEach(c=>c.addEventListener('click',()=>c.classList.toggle('active')));
      const build = document.getElementById('s-build');
      const copy = document.getElementById('s-copy');
      const out = document.getElementById('s-out');

      const make = ()=>{
        const name = document.getElementById('s-name').value.trim() || 'Client';
        const goal = document.getElementById('s-goal').value.trim() || 'General support';
        const cadence = document.getElementById('s-cadence').value;
        const chosen = Array.from(document.querySelectorAll('button.chip.active')).map(b=>b.dataset.val || b.dataset.value);
        const lines = [];
        lines.push(name + ' — quick plan');
        lines.push('Goal: ' + goal);
        if(chosen.length) lines.push('Approaches: ' + chosen.join(', '));
        lines.push('Cadence: ' + cadence + ' session(s)/month');
        lines.push('Bring this to your visit as a starting point. Not a clinical guarantee.');
        return lines.join('\n');
      };

      build.addEventListener('click',()=>{ out.textContent = make(); });
      copy.addEventListener('click',async()=>{
        try{ await navigator.clipboard.writeText(out.textContent); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1200);}catch(e){copy.textContent='Copy failed'}
      });
    })();
  </script>
